export const languageNames = {
  en: "languageEnglish",
  ar: "languageArabic",
  fr: "languageFrench",
  it: "languageItalian",
  zh: "languageChinese",
};

export function translate(language, key) {
  const value = translations[language]?.[key];
  if (value === undefined) {
    console.error(`Missing translation "${key}" for language "${language}".`);
    return `[${key}]`;
  }
  return value;
}
